Extra here: Could we actually test the cache?
```

const char* httpDateRegex =
    "(Mon|Tue|Wed|Thu|Fri|Sat|Sun), "
    "(0[1-9]|[12][0-9]|3[01]) "
    "(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) "
    "[0-9]{4} "
    "([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9] GMT";

// Call the cache twice in a row, returns the same
    const std::string firstCacheDate = server.getCachedDateStr();
    const std::string secondCacheDate = server.getCachedDateStr();


    EXPECT_THAT(firstCacheDate, MatchesRegex(httpDateRegex));
    EXPECT_THAT(secondCacheDate, MatchesRegex(httpDateRegex));
    EXPECT_EQ(firstCacheDate, secondCacheDate);
```
Two calls in a row..? 
```
    const std::string firstCacheDate = server.getCachedDateStr();

    std::this_thread::sleep_for(std::chrono::seconds(11));

    const std::string secondCacheDate = server.getCachedDateStr();

    EXPECT_THAT(firstCacheDate, MatchesRegex(httpDateRegex));
    EXPECT_THAT(secondCacheDate, MatchesRegex(httpDateRegex));
    EXPECT_NE(firstCacheDate, secondCacheDate );

```
11 seconds so they are in different cache windows..? An 11 delay isn't great so this might take mocking the clock.. Feel free to ignore
